JOIN hsdg.compliance_rules r ON r.code = v.code
ON CONFLICT (compliance_rule_id, version) DO NOTHING;

-- CBDT Circular (28 Sep 2026) on the new rules; 3CEB and the TP ITR are not extended.
INSERT INTO hsdg.government_extensions
  (compliance_rule_id, original_due_date, revised_due_date, notification_reference,
   applicable_population, effective_date, notes)
SELECT r.id, e.original, e.revised, 'CBDT Circular (28 Sep 2026)',
       'Assessees whose accounts are required to be audited, AY 2026-27; not TP (3CEB) cases',
       '2026-09-28'::date, 'Seeded with the calendar v2 rules.'
FROM jsonb_to_recordset($json$[
{"ruleCode":"IT_TAX_AUDIT","original":"2026-09-30","revised":"2026-10-21"},
{"ruleCode":"IT_ITR_AUDIT","original":"2026-10-31","revised":"2026-11-21"}
]$json$::jsonb)
  AS e("ruleCode" text, original date, revised date)
JOIN hsdg.compliance_rules r ON r.code = e."ruleCode"
WHERE NOT EXISTS (
  SELECT 1 FROM hsdg.government_extensions ge
   WHERE ge.compliance_rule_id = r.id AND ge.original_due_date = e.original
);

-- Retire the defective live rules by a new version (never edited in place).
UPDATE hsdg.compliance_rule_versions v
   SET effective_to = '2026-03-31'
  FROM hsdg.compliance_rules r
 WHERE r.id = v.compliance_rule_id
   AND r.code = ANY(ARRAY['TDS_STATEMENT_QUARTERLY','TDS_CERTIFICATES_QTR','TCS_STATEMENT_QUARTERLY','TDS_PAYMENT_MONTHLY','DIR3_KYC_ANNUAL','ROC_AOC4_DUE','ROC_MGT7_DUE','ADVANCE_TAX_Q1','BEN2_DECLARATION','BOARD_MEETING_QUARTERLY','CMP08_QUARTERLY','ESI_MONTHLY','FCGPR_REPORTING','GSTR1_MONTHLY','GSTR3B_MONTHLY','GSTR9C_ANNUAL','GSTR9_ANNUAL','GST_AMENDMENT_LIMITATION','GST_APPEAL_LIMITATION','GST_LUT_ANNUAL','INC20A_COMMENCEMENT','ITR_FILING_DUE','ITR_VERIFICATION_DUE','IT_APPEAL_LIMITATION','LABOUR_RETURNS_QTR','PAS3_ALLOTMENT','PF_MONTHLY','PT_MONTHLY','ROC_EVENT_FILING','TAX_AUDIT_44AB','TCS_COLLECTION_MONTHLY'])
   AND v.effective_to IS NULL
   AND v.effective_from < '2026-04-01'
   AND NOT EXISTS (SELECT 1 FROM hsdg.compliance_rule_versions x
                    WHERE x.compliance_rule_id = r.id AND x.effective_from >= '2026-04-01');

INSERT INTO hsdg.compliance_rule_versions
  (compliance_rule_id, version, effective_from, calculation_basis, offset_months, offset_days,
   fixed_month, fixed_day, working_day_adjustment, internal_sla_offset_days, condition, notes,
   offset_working_days, frequency, schedule, period_overrides, event_type, provisional_event_rule)
SELECT r.id, cur.version + 1, '2026-04-01',
       COALESCE(f.calculation_basis, cur.calculation_basis),
       COALESCE(f.offset_months, cur.offset_months),
       COALESCE(f.offset_days, cur.offset_days),
       CASE WHEN COALESCE(f.calculation_basis, cur.calculation_basis) = 'fixed_date' THEN cur.fixed_month END,
       CASE WHEN COALESCE(f.calculation_basis, cur.calculation_basis) = 'fixed_date' THEN cur.fixed_day END,
       'none', cur.internal_sla_offset_days, cur.condition,
       'calendar-v2 retirement: ' || COALESCE(cur.notes, r.name),
       cur.offset_working_days, f.frequency, f.schedule, f.period_overrides, f.event_type,
       f.provisional_event_rule
FROM jsonb_to_recordset($json$[
{"code":"TDS_STATEMENT_QUARTERLY","frequency":"quarterly","calculation_basis":"schedule","schedule":[{"period":"Q1","month":7,"day":31,"year_offset":0},{"period":"Q2","month":10,"day":31,"year_offset":0},{"period":"Q3","month":1,"day":31,"year_offset":1},{"period":"Q4","month":5,"day":31,"year_offset":1}]},
{"code":"TDS_CERTIFICATES_QTR","frequency":"quarterly","calculation_basis":"schedule","schedule":[{"period":"Q1","month":8,"day":15,"year_offset":0},{"period":"Q2","month":11,"day":15,"year_offset":0},{"period":"Q3","month":2,"day":15,"year_offset":1},{"period":"Q4","month":6,"day":15,"year_offset":1}]},
{"code":"TCS_STATEMENT_QUARTERLY","frequency":"quarterly","calculation_basis":"schedule","schedule":[{"period":"Q1","month":7,"day":31,"year_offset":0},{"period":"Q2","month":10,"day":31,"year_offset":0},{"period":"Q3","month":1,"day":31,"year_offset":1},{"period":"Q4","month":5,"day":31,"year_offset":1}]},
{"code":"TDS_PAYMENT_MONTHLY","frequency":"monthly","period_overrides":{"03":{"month":4,"day":30}}},
{"code":"DIR3_KYC_ANNUAL","frequency":"triennial","calculation_basis":"schedule","schedule":[{"period":"FY","month":6,"day":30,"year_offset":1}]},
{"code":"ROC_AOC4_DUE","frequency":"annual","calculation_basis":"event_date","offset_months":0,"offset_days":30,"event_type":"agm","provisional_event_rule":{"month":9,"day":30,"year_offset":1}},
{"code":"ROC_MGT7_DUE","frequency":"annual","calculation_basis":"event_date","offset_months":0,"offset_days":60,"event_type":"agm","provisional_event_rule":{"month":9,"day":30,"year_offset":1}},
{"code":"ADVANCE_TAX_Q1"},
{"code":"BEN2_DECLARATION"},
{"code":"BOARD_MEETING_QUARTERLY"},
{"code":"CMP08_QUARTERLY"},
{"code":"ESI_MONTHLY"},
{"code":"FCGPR_REPORTING"},
{"code":"GSTR1_MONTHLY"},
{"code":"GSTR3B_MONTHLY"},
{"code":"GSTR9C_ANNUAL"},
{"code":"GSTR9_ANNUAL"},
{"code":"GST_AMENDMENT_LIMITATION"},
{"code":"GST_APPEAL_LIMITATION"},
{"code":"GST_LUT_ANNUAL"},
{"code":"INC20A_COMMENCEMENT"},
{"code":"ITR_FILING_DUE"},
{"code":"ITR_VERIFICATION_DUE"},
{"code":"IT_APPEAL_LIMITATION"},
{"code":"LABOUR_RETURNS_QTR"},
{"code":"PAS3_ALLOTMENT"},
{"code":"PF_MONTHLY"},
{"code":"PT_MONTHLY"},
{"code":"ROC_EVENT_FILING"},
{"code":"TAX_AUDIT_44AB"},
{"code":"TCS_COLLECTION_MONTHLY"}
]$json$::jsonb)
  AS f(code text, frequency text, calculation_basis text, offset_months int, offset_days int,
       schedule jsonb, period_overrides jsonb, event_type text, provisional_event_rule jsonb)
JOIN hsdg.compliance_rules r ON r.code = f.code
JOIN LATERAL (
  SELECT * FROM hsdg.compliance_rule_versions v
   WHERE v.compliance_rule_id = r.id ORDER BY v.version DESC LIMIT 1
) cur ON true
WHERE cur.effective_from < '2026-04-01';

ALTER TABLE hsdg.services FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.compliance_rules FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.compliance_rule_versions FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.government_extensions FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.compliance_instances FORCE ROW LEVEL SECURITY;

